onSelectQuery:
{{
  (async () => {
    const queryId =
      CW_Workspace.model.selectedQueryId || "";

    const queryName =
      CW_Workspace.model.selectedQueryName || "";

    if (!queryId) {
      return;
    }

    await storeValue(
      "selectedQueryId",
      queryId
    );

    await storeValue(
      "selectedQueryName",
      queryName
    );

    await q_ws_list_web_mentions.run();
  })()
}}

srcDoc.css:
@charset "UTF-8";
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

body {
  font-family: "DM Sans", sans-serif;
  background: transparent;
  color: #2F323B;
}

.workspace-shell {
  --ink: #2F323B;
  --ink-soft: #3C414B;
  --blue: #2972A9;
  --cyan: #2E9BCB;
  --light-blue: #A7CDDE;
  --paper: #FFFFFF;
  --surface: #F7FAFC;
  --surface-blue: rgba(167, 205, 222, 0.14);
  --line: rgba(167, 205, 222, 0.55);
  --line-soft: rgba(167, 205, 222, 0.28);
  --text: #2F323B;
  --muted: #727780;
  width: 100%;
  height: 100%;
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 8px;
  background: radial-gradient(circle at 18% 0%, rgba(46, 155, 203, 0.1), transparent 26%), linear-gradient(180deg, #F8FBFD 0%, #FFFFFF 100%);
}

/* =========================================================
   HEADER
   ========================================================= */
.workspace-header {
  min-height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 10px 14px 10px 16px;
  border: 1px solid var(--line);
  border-radius: 18px 18px 10px 10px;
  background: linear-gradient(110deg, #2F323B 0%, #343B47 58%, #244F6D 100%);
  box-shadow: 0 12px 30px rgba(47, 50, 59, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  overflow: hidden;
  position: relative;
}

/* halo tecnológico sutil */
.workspace-header::after {
  content: "";
  position: absolute;
  width: 280px;
  height: 160px;
  right: 18%;
  top: -95px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(46, 155, 203, 0.24) 0%, rgba(46, 155, 203, 0.05) 42%, transparent 70%);
  pointer-events: none;
}

/* =========================================================
   BRAND
   ========================================================= */
.workspace-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 190px;
  position: relative;
  z-index: 2;
}

.brand-symbol {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border-radius: 13px;
  background: linear-gradient(145deg, rgba(46, 155, 203, 0.22), rgba(41, 114, 169, 0.1));
  border: 1px solid rgba(167, 205, 222, 0.22);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.signal-bar {
  display: block;
  width: 3px;
  border-radius: 999px;
  background: linear-gradient(180deg, #65C8EC, #2E9BCB);
  box-shadow: 0 0 8px rgba(46, 155, 203, 0.35);
}

.bar-1 {
  height: 10px;
}

.bar-2 {
  height: 18px;
}

.bar-3 {
  height: 27px;
}

.bar-4 {
  height: 18px;
}

.bar-5 {
  height: 10px;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.brand-copy strong {
  color: #FFFFFF;
  font-family: "Playfair Display", serif;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.15;
  white-space: nowrap;
}

.brand-copy span {
  margin-top: 3px;
  color: rgba(255, 255, 255, 0.47);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  white-space: nowrap;
}

/* =========================================================
   TOOLBAR
   ========================================================= */
.workspace-tools {
  flex: 1;
  min-width: 0;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  position: relative;
  z-index: 2;
}

/* =========================================================
   SEARCH
   ========================================================= */
.workspace-search {
  flex: 1;
  max-width: 410px;
  min-width: 190px;
  height: 42px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 13px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(10px);
  transition: border-color 0.2s, background 0.2s, box-shadow 0.2s;
}

.workspace-search:focus-within {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(46, 155, 203, 0.75);
  box-shadow: 0 0 0 3px rgba(46, 155, 203, 0.12);
}

.search-icon {
  width: 15px;
  height: 15px;
  position: relative;
  flex-shrink: 0;
}

.search-icon::before {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  border: 1.7px solid rgba(255, 255, 255, 0.65);
  border-radius: 50%;
  left: 0;
  top: 0;
}

.search-icon::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 1.7px;
  background: rgba(255, 255, 255, 0.65);
  transform: rotate(45deg);
  left: 9px;
  top: 10px;
  border-radius: 2px;
}

.workspace-search input {
  width: 100%;
  border: none;
  outline: none;
  background: transparent;
  color: #FFFFFF;
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
}

.workspace-search input::placeholder {
  color: rgba(255, 255, 255, 0.42);
}

/* =========================================================
   CONTEXTO / CONSULTA SELECCIONADA
   ========================================================= */
.context-selector {
  height: 42px;
  min-width: 180px;
  max-width: 225px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.08);
  color: #FFFFFF;
  font-family: "DM Sans", sans-serif;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s;
}

.context-selector:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(46, 155, 203, 0.62);
}

.context-status {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #47D7A0;
  box-shadow: 0 0 0 4px rgba(71, 215, 160, 0.12);
  flex-shrink: 0;
}

.context-copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.context-copy small {
  color: rgba(255, 255, 255, 0.43);
  font-size: 7px;
  line-height: 1.2;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.context-copy strong {
  width: 100%;
  margin-top: 2px;
  overflow: hidden;
  color: #FFFFFF;
  font-size: 10px;
  font-weight: 600;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-chevron,
.user-chevron {
  width: 7px;
  height: 7px;
  border-right: 1.5px solid rgba(255, 255, 255, 0.55);
  border-bottom: 1.5px solid rgba(255, 255, 255, 0.55);
  transform: rotate(45deg) translateY(-2px);
  flex-shrink: 0;
}

/* =========================================================
   SELECTOR HORIZONTAL DE CONSULTAS
   ========================================================= */
.query-selector-dropdown {
  position: absolute;
  width: min(860px, 100% - 16px);
  max-width: calc(100% - 16px);
  z-index: 50;
  padding: 8px;
  border-radius: 14px;
  border: 1px solid rgba(167, 205, 222, 0.72);
  background: rgba(255, 255, 255, 0.985);
  box-shadow: 0 18px 42px rgba(47, 50, 59, 0.18), 0 3px 12px rgba(47, 50, 59, 0.08);
  backdrop-filter: blur(18px);
}

.query-selector-dropdown[hidden] {
  display: none !important;
}

.query-selector-dropdown__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 8px 8px;
  border-bottom: 1px solid var(--line-soft);
}

.query-selector-dropdown__header > div {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.query-selector-dropdown__header small {
  color: var(--muted);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.query-selector-dropdown__header strong {
  color: var(--text);
  font-size: 11px;
  font-weight: 700;
}

.query-selector-count {
  min-width: 25px;
  height: 25px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 7px;
  flex-shrink: 0;
  border-radius: 999px;
  background: rgba(41, 114, 169, 0.09);
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
}

/* ---------------------------------------------------------
   FILA HORIZONTAL
   --------------------------------------------------------- */
.query-selector-list {
  width: 100%;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 7px;
  padding: 7px 2px 5px;
  overflow-x: auto;
  overflow-y: hidden;
  max-height: none;
  scrollbar-width: thin;
  scrollbar-color: rgba(41, 114, 169, 0.35) rgba(167, 205, 222, 0.1);
  scroll-behavior: smooth;
  scroll-snap-type: x proximity;
  overscroll-behavior-x: contain;
}

.query-selector-list::-webkit-scrollbar {
  height: 6px;
}

.query-selector-list::-webkit-scrollbar-track {
  border-radius: 999px;
  background: rgba(167, 205, 222, 0.1);
}

.query-selector-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(41, 114, 169, 0.32);
}

.query-selector-list::-webkit-scrollbar-thumb:hover {
  background: rgba(41, 114, 169, 0.5);
}

/* ---------------------------------------------------------
   TARJETA DE CONSULTA
   --------------------------------------------------------- */
.query-selector-option {
  flex: 0 0 200px;
  width: 200px;
  min-width: 200px;
  max-width: 200px;
  min-height: 52px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 9px;
  scroll-snap-align: start;
  border-radius: 10px;
  border: 1px solid rgba(167, 205, 222, 0.22);
  background: #FFFFFF;
  color: var(--text);
  font-family: "DM Sans", sans-serif;
  cursor: pointer;
  text-align: left;
  box-shadow: 0 2px 8px rgba(47, 50, 59, 0.03);
  transition: background 0.16s, border-color 0.16s, transform 0.16s, box-shadow 0.16s;
}

.query-selector-option:hover {
  background: rgba(167, 205, 222, 0.12);
  border-color: rgba(46, 155, 203, 0.42);
  box-shadow: 0 4px 12px rgba(41, 114, 169, 0.08);
  transform: translateY(-1px);
}

.query-selector-option:active {
  transform: translateY(0);
}

.query-selector-option.selected {
  background: linear-gradient(135deg, rgba(41, 114, 169, 0.11), rgba(46, 155, 203, 0.08));
  border-color: rgba(46, 155, 203, 0.52);
  box-shadow: inset 0 0 0 1px rgba(46, 155, 203, 0.07);
}

/* estado */
.query-selector-option__status {
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: 50%;
  background: #47D7A0;
  box-shadow: 0 0 0 4px rgba(71, 215, 160, 0.1);
}

.query-selector-option__status.inactive {
  background: #9CA3AF;
  box-shadow: 0 0 0 4px rgba(156, 163, 175, 0.1);
}

/* contenido */
.query-selector-option__copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.query-selector-option__copy strong {
  width: 100%;
  overflow: hidden;
  color: var(--text);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-selector-option__copy small {
  width: 100%;
  overflow: hidden;
  color: var(--muted);
  font-size: 8px;
  font-weight: 500;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* check */
.query-selector-option__check {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--blue);
  font-size: 10px;
  font-weight: 800;
}

/* vacío */
.query-selector-empty {
  width: 100%;
  padding: 14px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  text-align: center;
}

.query-selector-empty strong {
  color: var(--text);
  font-size: 10px;
  font-weight: 700;
}

.query-selector-empty span {
  font-size: 8px;
  line-height: 1.4;
}

/* selector abierto */
.context-selector.is-open {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(46, 155, 203, 0.72);
  box-shadow: 0 0 0 3px rgba(46, 155, 203, 0.1);
}

.context-selector.is-open .context-chevron {
  transform: rotate(225deg) translate(-1px, -1px);
}

/* =========================================================
   NOTIFICACIONES
   ========================================================= */
.header-icon-button {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.08);
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
}

.header-icon-button:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(46, 155, 203, 0.62);
}

.notification-icon {
  width: 15px;
  height: 16px;
  position: relative;
}

.notification-icon::before {
  content: "";
  position: absolute;
  width: 10px;
  height: 11px;
  left: 2px;
  top: 0;
  border: 1.5px solid rgba(255, 255, 255, 0.75);
  border-radius: 7px 7px 4px 4px;
}

.notification-icon::after {
  content: "";
  position: absolute;
  width: 4px;
  height: 2px;
  left: 5px;
  bottom: 0;
  border-radius: 0 0 4px 4px;
  background: rgba(255, 255, 255, 0.75);
}

/* =========================================================
   USUARIO
   ========================================================= */
.workspace-user {
  height: 42px;
  min-width: 150px;
  max-width: 200px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 10px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.08);
  font-family: "DM Sans", sans-serif;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
}

.workspace-user:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(46, 155, 203, 0.62);
}

.workspace-user-avatar {
  width: 28px;
  height: 28px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: linear-gradient(145deg, #2E9BCB, #2972A9);
  color: #FFFFFF;
  font-size: 10px;
  font-weight: 700;
  box-shadow: 0 5px 14px rgba(46, 155, 203, 0.22);
}

.workspace-user-copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.workspace-user-copy strong {
  width: 100%;
  overflow: hidden;
  color: #FFFFFF;
  font-size: 9px;
  font-weight: 600;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-user-copy small {
  margin-top: 1px;
  color: rgba(255, 255, 255, 0.42);
  font-size: 7px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* =========================================================
   NAVEGACIÓN POR PESTAÑAS
   ========================================================= */
.workspace-tabs {
  min-height: 66px;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 5px;
  padding: 6px;
  margin-top: 5px;
  border-radius: 10px 10px 18px 18px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 10px 24px rgba(47, 50, 59, 0.07);
  backdrop-filter: blur(16px);
}

.workspace-tab {
  position: relative;
  min-width: 0;
  min-height: 52px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 10px;
  border: none;
  border-radius: 12px;
  background: transparent;
  color: var(--muted);
  font-family: "DM Sans", sans-serif;
  cursor: pointer;
  overflow: hidden;
  transition: background 0.2s, color 0.2s, box-shadow 0.2s, transform 0.2s;
}

.workspace-tab:hover {
  color: var(--blue);
  background: rgba(167, 205, 222, 0.15);
}

.workspace-tab.active {
  color: #FFFFFF;
  background: linear-gradient(135deg, #2972A9, #2E9BCB);
  box-shadow: 0 7px 18px rgba(41, 114, 169, 0.22);
  transform: translateY(-1px);
}

.workspace-tab.active::after {
  content: "";
  position: absolute;
  width: 70px;
  height: 70px;
  right: -25px;
  top: -35px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
}

.tab-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  position: relative;
  z-index: 2;
}

.tab-copy strong {
  width: 100%;
  overflow: hidden;
  font-size: 10px;
  font-weight: 700;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tab-copy small {
  width: 100%;
  margin-top: 2px;
  overflow: hidden;
  color: #8C929A;
  font-size: 7px;
  font-weight: 500;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-tab.active .tab-copy small {
  color: rgba(255, 255, 255, 0.7);
}

/* =========================================================
   ICONOS PESTAÑAS
   ========================================================= */
.tab-icon {
  width: 27px;
  height: 27px;
  border-radius: 9px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 2;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
}

.workspace-tab.active .tab-icon {
  background: rgba(255, 255, 255, 0.17);
  color: #FFFFFF;
}

/* resumen */
.tab-icon-summary::before {
  content: "";
  width: 13px;
  height: 13px;
  border: 1.5px solid currentColor;
  border-radius: 3px;
  box-shadow: inset 5px 0 0 rgba(41, 114, 169, 0.12);
}

.workspace-tab.active .tab-icon-summary::before {
  box-shadow: inset 5px 0 0 rgba(255, 255, 255, 0.18);
}

.tab-icon-summary::after {
  content: "";
  position: absolute;
  width: 5px;
  height: 1.5px;
  right: 5px;
  top: 8px;
  background: currentColor;
  box-shadow: 0 4px 0 currentColor;
}

/* consultas */
.tab-icon-queries::before {
  content: "";
  width: 13px;
  height: 13px;
  border: 1.5px solid currentColor;
  border-radius: 3px;
}

.tab-icon-queries::after {
  content: "";
  position: absolute;
  width: 7px;
  height: 1.5px;
  background: currentColor;
  box-shadow: 0 4px 0 currentColor;
  left: 10px;
  top: 9px;
}

/* monitoreo */
.tab-icon-monitoring::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 4px rgba(46, 155, 203, 0.12);
}

.workspace-tab.active .tab-icon-monitoring::before {
  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.15);
}

.tab-icon-monitoring::after {
  content: "";
  position: absolute;
  width: 17px;
  height: 17px;
  border: 1.4px solid currentColor;
  border-radius: 50%;
  opacity: 0.34;
}

/* análisis */
.tab-icon-analysis::before {
  content: "";
  width: 3px;
  height: 7px;
  border-radius: 2px;
  background: currentColor;
  box-shadow: 5px -3px 0 currentColor, 10px -7px 0 currentColor;
  transform: translate(-5px, 3px);
}

.tab-icon-analysis::after {
  content: "";
  position: absolute;
  width: 15px;
  height: 11px;
  border-left: 1.4px solid currentColor;
  border-bottom: 1.4px solid currentColor;
  left: 6px;
  bottom: 6px;
  border-radius: 0 0 0 2px;
}

/* reportes */
.tab-icon-reports::before {
  content: "";
  width: 11px;
  height: 14px;
  border: 1.5px solid currentColor;
  border-radius: 2px;
}

.tab-icon-reports::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 1px;
  background: currentColor;
  box-shadow: 0 4px 0 currentColor;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */
@media (max-width: 1120px) {
  .workspace-search {
    max-width: 290px;
  }
  .context-selector {
    min-width: 155px;
  }
  .workspace-user {
    min-width: 125px;
  }
  .tab-copy small {
    display: none;
  }
  .workspace-tab {
    justify-content: center;
  }
  .query-selector-dropdown {
    width: min(760px, 100% - 16px);
  }
  .query-selector-option {
    flex-basis: 190px;
