  background:
    rgba(41, 114, 169, 0.09);

  color: var(--blue);

  font-size: 9px;
  font-weight: 700;
}


/* ---------------------------------------------------------
   FILA HORIZONTAL
   --------------------------------------------------------- */

.query-selector-list {
  width: 100%;

  display: flex;
  flex-direction: row;
  align-items: stretch;

  gap: 7px;

  padding:
    7px 2px 5px;

  overflow-x: auto;
  overflow-y: hidden;

  max-height: none;

  scrollbar-width: thin;

  scrollbar-color:
    rgba(41, 114, 169, 0.35)
    rgba(167, 205, 222, 0.10);

  scroll-behavior: smooth;

  scroll-snap-type:
    x proximity;

  overscroll-behavior-x:
    contain;
}

.query-selector-list::-webkit-scrollbar {
  height: 6px;
}

.query-selector-list::-webkit-scrollbar-track {
  border-radius: 999px;

  background:
    rgba(167, 205, 222, 0.10);
}

.query-selector-list::-webkit-scrollbar-thumb {
  border-radius: 999px;

  background:
    rgba(41, 114, 169, 0.32);
}

.query-selector-list::-webkit-scrollbar-thumb:hover {
  background:
    rgba(41, 114, 169, 0.50);
}


/* ---------------------------------------------------------
   TARJETA DE CONSULTA
   --------------------------------------------------------- */

.query-selector-option {
  flex:
    0 0 200px;

  width: 200px;
  min-width: 200px;
  max-width: 200px;

  min-height: 52px;

  display: flex;
  align-items: center;

  gap: 8px;

  padding:
    8px 9px;

  scroll-snap-align: start;

  border-radius: 10px;

  border:
    1px solid
    rgba(167, 205, 222, 0.22);

  background:
    #FFFFFF;

  color: var(--text);

  font-family:
    "DM Sans",
    sans-serif;

  cursor: pointer;

  text-align: left;

  box-shadow:
    0 2px 8px
    rgba(47, 50, 59, 0.03);

  transition:
    background 0.16s,
    border-color 0.16s,
    transform 0.16s,
    box-shadow 0.16s;
}

.query-selector-option:hover {
  background:
    rgba(167, 205, 222, 0.12);

  border-color:
    rgba(46, 155, 203, 0.42);

  box-shadow:
    0 4px 12px
    rgba(41, 114, 169, 0.08);

  transform:
    translateY(-1px);
}

.query-selector-option:active {
  transform:
    translateY(0);
}

.query-selector-option.selected {
  background:
    linear-gradient(
      135deg,
      rgba(41, 114, 169, 0.11),
      rgba(46, 155, 203, 0.08)
    );

  border-color:
    rgba(46, 155, 203, 0.52);

  box-shadow:
    inset 0 0 0 1px
    rgba(46, 155, 203, 0.07);
}


/* estado */

.query-selector-option__status {
  width: 8px;
  height: 8px;

  flex-shrink: 0;

  border-radius: 50%;

  background: #47D7A0;

  box-shadow:
    0 0 0 4px
    rgba(71, 215, 160, 0.10);
}

.query-selector-option__status.inactive {
  background: #9CA3AF;

  box-shadow:
    0 0 0 4px
    rgba(156, 163, 175, 0.10);
}


/* contenido */

.query-selector-option__copy {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;

  gap: 2px;
}

.query-selector-option__copy strong {
  width: 100%;

  overflow: hidden;

  color: var(--text);

  font-size: 10px;
  font-weight: 700;

  line-height: 1.25;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-selector-option__copy small {
  width: 100%;

  overflow: hidden;

  color: var(--muted);

  font-size: 8px;
  font-weight: 500;

  line-height: 1.25;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* check */

.query-selector-option__check {
  width: 18px;
  height: 18px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 6px;

  color: var(--blue);

  font-size: 10px;
  font-weight: 800;
}


/* vacío */

.query-selector-empty {
  width: 100%;

  padding: 14px 10px;

  display: flex;
  flex-direction: column;
  align-items: center;

  gap: 4px;

  color: var(--muted);

  text-align: center;
}

.query-selector-empty strong {
  color: var(--text);

  font-size: 10px;
  font-weight: 700;
}

.query-selector-empty span {
  font-size: 8px;

  line-height: 1.4;
}


/* selector abierto */

.context-selector.is-open {
  background:
    rgba(255, 255, 255, 0.14);

  border-color:
    rgba(46, 155, 203, 0.72);

  box-shadow:
    0 0 0 3px
    rgba(46, 155, 203, 0.10);
}

.context-selector.is-open
.context-chevron {
  transform:
    rotate(225deg)
    translate(-1px, -1px);
}


/* =========================================================
   NOTIFICACIONES
   ========================================================= */

.header-icon-button {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  border:
    1px solid
    rgba(255, 255, 255, 0.12);

  background:
    rgba(255, 255, 255, 0.08);

  cursor: pointer;

  transition:
    background 0.2s,
    border-color 0.2s;
}

.header-icon-button:hover {
  background:
    rgba(255, 255, 255, 0.12);

  border-color:
    rgba(46, 155, 203, 0.62);
}

.notification-icon {
  width: 15px;
  height: 16px;

  position: relative;
}

.notification-icon::before {
  content: "";

  position: absolute;

  width: 10px;
  height: 11px;

  left: 2px;
  top: 0;

  border:
    1.5px solid
    rgba(255, 255, 255, 0.75);

  border-radius:
    7px 7px 4px 4px;
}

.notification-icon::after {
  content: "";

  position: absolute;

  width: 4px;
  height: 2px;

  left: 5px;
  bottom: 0;

  border-radius:
    0 0 4px 4px;

  background:
    rgba(255, 255, 255, 0.75);
}


/* =========================================================
   USUARIO
   ========================================================= */

.workspace-user {
  height: 42px;

  min-width: 150px;
  max-width: 200px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding: 0 10px;

  border-radius: 12px;

  border:
    1px solid
    rgba(255, 255, 255, 0.12);

  background:
    rgba(255, 255, 255, 0.08);

  font-family:
    "DM Sans",
    sans-serif;

  cursor: pointer;

  transition:
    background 0.2s,
    border-color 0.2s;
}

.workspace-user:hover {
  background:
    rgba(255, 255, 255, 0.12);

  border-color:
    rgba(46, 155, 203, 0.62);
}

.workspace-user-avatar {
  width: 28px;
  height: 28px;

  border-radius: 9px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  background:
    linear-gradient(
      145deg,
      #2E9BCB,
      #2972A9
    );

  color: #FFFFFF;

  font-size: 10px;
  font-weight: 700;

  box-shadow:
    0 5px 14px
    rgba(46, 155, 203, 0.22);
}

.workspace-user-copy {
  min-width: 0;

  flex: 1;

  display: flex;
  flex-direction: column;

  align-items: flex-start;
}

.workspace-user-copy strong {
  width: 100%;

  overflow: hidden;

  color: #FFFFFF;

  font-size: 9px;
  font-weight: 600;

  text-align: left;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-user-copy small {
  margin-top: 1px;

  color:
    rgba(255, 255, 255, 0.42);

  font-size: 7px;

  text-transform: uppercase;

  letter-spacing: 0.08em;
}


/* =========================================================
   NAVEGACIÓN POR PESTAÑAS
   ========================================================= */

.workspace-tabs {
  min-height: 66px;

  display: grid;

  grid-template-columns:
    repeat(
      5,
      minmax(0, 1fr)
    );

  gap: 5px;

  padding: 6px;

  margin-top: 5px;

  border-radius:
    10px 10px 18px 18px;

  border:
    1px solid var(--line);

  background:
    rgba(255, 255, 255, 0.92);

  box-shadow:
    0 10px 24px
    rgba(47, 50, 59, 0.07);

  backdrop-filter:
    blur(16px);
}

.workspace-tab {
  position: relative;

  min-width: 0;
  min-height: 52px;

  display: flex;
  align-items: center;

  gap: 9px;

  padding:
    7px 10px;

  border: none;

  border-radius: 12px;

  background: transparent;

  color: var(--muted);

  font-family:
    "DM Sans",
    sans-serif;

  cursor: pointer;

  overflow: hidden;

  transition:
    background 0.2s,
    color 0.2s,
    box-shadow 0.2s,
    transform 0.2s;
}

.workspace-tab:hover {
  color: var(--blue);

  background:
    rgba(167, 205, 222, 0.15);
}

.workspace-tab.active {
  color: #FFFFFF;

  background:
    linear-gradient(
      135deg,
      #2972A9,
      #2E9BCB
    );

  box-shadow:
    0 7px 18px
    rgba(41, 114, 169, 0.22);

  transform:
    translateY(-1px);
}

.workspace-tab.active::after {
  content: "";

  position: absolute;

  width: 70px;
  height: 70px;

  right: -25px;
  top: -35px;

  border-radius: 50%;

  background:
    rgba(255, 255, 255, 0.10);
}

.tab-copy {
  min-width: 0;

  display: flex;
  flex-direction: column;

  align-items: flex-start;

  position: relative;
  z-index: 2;
}

.tab-copy strong {
  width: 100%;

  overflow: hidden;

  font-size: 10px;
  font-weight: 700;

  text-align: left;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.tab-copy small {
  width: 100%;

  margin-top: 2px;

  overflow: hidden;

  color: #8C929A;

  font-size: 7px;
  font-weight: 500;

  text-align: left;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.workspace-tab.active .tab-copy small {
  color:
    rgba(255, 255, 255, 0.70);
}


/* =========================================================
   ICONOS PESTAÑAS
   ========================================================= */

.tab-icon {
  width: 27px;
  height: 27px;

  border-radius: 9px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  position: relative;
  z-index: 2;

  background:
    rgba(41, 114, 169, 0.08);

  color: var(--blue);
}

.workspace-tab.active .tab-icon {
  background:
    rgba(255, 255, 255, 0.17);

  color: #FFFFFF;
}


/* resumen */

.tab-icon-summary::before {
  content: "";

  width: 13px;
  height: 13px;

  border:
    1.5px solid
    currentColor;

  border-radius: 3px;

  box-shadow:
    inset 5px 0 0
    rgba(41, 114, 169, 0.12);
}

.workspace-tab.active
.tab-icon-summary::before {
  box-shadow:
    inset 5px 0 0
    rgba(255, 255, 255, 0.18);
}

.tab-icon-summary::after {
  content: "";

  position: absolute;

  width: 5px;
  height: 1.5px;

  right: 5px;
  top: 8px;

  background: currentColor;

  box-shadow:
    0 4px 0
    currentColor;
}


/* consultas */

.tab-icon-queries::before {
  content: "";

  width: 13px;
  height: 13px;

  border:
    1.5px solid
    currentColor;

  border-radius: 3px;
}

.tab-icon-queries::after {
  content: "";

  position: absolute;

  width: 7px;
  height: 1.5px;

  background: currentColor;

  box-shadow:
    0 4px 0
    currentColor;

  left: 10px;
  top: 9px;
}


/* monitoreo */

.tab-icon-monitoring::before {
  content: "";

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: currentColor;

  box-shadow:
    0 0 0 4px
    rgba(46, 155, 203, 0.12);
}

.workspace-tab.active
.tab-icon-monitoring::before {
  box-shadow:
    0 0 0 4px
    rgba(255, 255, 255, 0.15);
}

.tab-icon-monitoring::after {
  content: "";

  position: absolute;

  width: 17px;
  height: 17px;

  border:
    1.4px solid
    currentColor;

  border-radius: 50%;

  opacity: 0.34;
}


/* análisis */

.tab-icon-analysis::before {
  content: "";

  width: 3px;
  height: 7px;

  border-radius: 2px;

  background: currentColor;

  box-shadow:
    5px -3px 0
    currentColor,
    10px -7px 0
    currentColor;

  transform:
    translate(
      -5px,
      3px
    );
}

.tab-icon-analysis::after {
  content: "";

  position: absolute;

  width: 15px;
  height: 11px;

  border-left:
    1.4px solid
    currentColor;

  border-bottom:
    1.4px solid
    currentColor;

  left: 6px;
  bottom: 6px;

  border-radius:
    0 0 0 2px;
}


/* reportes */

.tab-icon-reports::before {
  content: "";

  width: 11px;
  height: 14px;

  border:
    1.5px solid
    currentColor;

  border-radius: 2px;
}

.tab-icon-reports::after {
  content: "";

  position: absolute;

  width: 6px;
  height: 1px;

  background:
    currentColor;

  box-shadow:
    0 4px 0
    currentColor;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1120px) {

  .workspace-search {
    max-width: 290px;
  }

  .context-selector {
    min-width: 155px;
  }

  .workspace-user {
    min-width: 125px;
  }

  .tab-copy small {
    display: none;
  }

  .workspace-tab {
    justify-content: center;
  }

  .query-selector-dropdown {
    width:
      min(
        760px,
        calc(100% - 16px)
      );
  }

  .query-selector-option {
    flex-basis: 190px;

    width: 190px;
    min-width: 190px;
    max-width: 190px;
  }
}


@media (max-width: 900px) {

  .workspace-brand {
    min-width: auto;
  }

  .brand-copy span {
    display: none;
  }

  .workspace-search {
    display: none;
  }

  .workspace-user-copy {
    display: none;
  }

  .workspace-user {
    min-width: 42px;
    width: 42px;

    padding: 0;

    justify-content: center;
  }

  .workspace-user .user-chevron {
    display: none;
  }

  .workspace-tabs {
    overflow-x: auto;

    grid-template-columns:
      repeat(
        5,
        150px
      );
  }

  .query-selector-dropdown {
    width:
      calc(100% - 16px);
  }

  .query-selector-option {
    flex-basis: 180px;

    width: 180px;
    min-width: 180px;
    max-width: 180px;
  }
}

