appsmith.onReady(function () {

  var validSections = [
    'summary',
    'queries',
    'monitoring',
    'analysis',
    'reports'
  ];

  var sectionDefaults = {
    summary: 'summary',
    queries: 'constructor',
    monitoring: 'mentions',
    analysis: 'sentiment',
    reports: 'reports'
  };

  var sectionTabs = {
    summary: [
      'summary'
    ],
    queries: [
      'constructor',
      'all'
    ],
    monitoring: [
      'trends',
      'live',
      'mentions',
      'alerts'
    ],
    analysis: [
      'sentiment',
      'actors'
    ],
    reports: [
      'reports'
    ]
  };

  /*
   * La navegación pertenece al Workspace.
   * Siempre inicia en Resumen al cargar.
   */
  var currentSection = 'summary';
  var currentTab = 'summary';

  var navigationSyncPending = false;
  var querySelectorOpen = false;


  function getModel(modelOverride) {
    return (
      modelOverride ||
      appsmith.model ||
      {}
    );
  }


  function getInitial(value) {
    var text =
      String(
        value || ''
      ).trim();

    if (!text) {
      return 'U';
    }

    return text
      .charAt(0)
      .toUpperCase();
  }


  function normalizeValue(value) {
    return String(
      value || ''
    )
      .trim()
      .toLowerCase();
  }


  function asArray(value) {
    if (Array.isArray(value)) {
      return value;
    }

    if (
      typeof value !== 'string' ||
      value.trim() === ''
    ) {
      return [];
    }

    var text =
      value.trim();

    try {
      var parsed =
        JSON.parse(text);

      return Array.isArray(parsed)
        ? parsed
        : [];
    } catch (directError) {
      try {
        var decoded =
          decodeURIComponent(text);

        var decodedParsed =
          JSON.parse(decoded);

        return Array.isArray(decodedParsed)
          ? decodedParsed
          : [];
      } catch (decodedError) {
        return [];
      }
    }
  }


  function getQueries(modelOverride) {
    var model =
      getModel(
        modelOverride
      );

    return asArray(
      model.queries
    );
  }


  function getSelectedQueryId(modelOverride) {
    var model =
      getModel(
        modelOverride
      );

    return String(
      model.selectedQueryId ||
      model.activeQueryId ||
      ''
    ).trim();
  }


  function getSelectedQueryName(modelOverride) {
    var model =
      getModel(
        modelOverride
      );

    return String(
      model.selectedQueryName ||
      model.activeQueryName ||
      ''
    ).trim();
  }


  function findQueryById(
    queryId,
    modelOverride
  ) {
    var id =
      String(
        queryId || ''
      ).trim();

    if (!id) {
      return null;
    }

    var queries =
      getQueries(
        modelOverride
      );

    for (
      var i = 0;
      i < queries.length;
      i += 1
    ) {
      if (
        queries[i] &&
        String(
          queries[i].id || ''
        ).trim() === id
      ) {
        return queries[i];
      }
    }

    return null;
  }


  function isValidSection(sectionId) {
    return (
      validSections.indexOf(
        sectionId
      ) !== -1
    );
  }


  function isValidTabForSection(
    tabId,
    sectionId
  ) {
    var tabs =
      sectionTabs[
        sectionId
      ] || [];

    return (
      tabs.indexOf(
        tabId
      ) !== -1
    );
  }


  function getDefaultTab(
    sectionId
  ) {
    return (
      sectionDefaults[
        sectionId
      ] ||
      'constructor'
    );
  }


  function setActiveSectionVisual(
    sectionId
  ) {
    var tabs =
      document.querySelectorAll(
        '.workspace-tab'
      );

    tabs.forEach(
      function (tab) {
        var isActive =
          tab.getAttribute(
            'data-section'
          ) === sectionId;

        tab.classList.toggle(
          'active',
          isActive
        );

        tab.setAttribute(
          'aria-selected',
          isActive
            ? 'true'
            : 'false'
        );
      }
    );
  }


  function syncUser(
    modelOverride
  ) {
    var model =
      getModel(
        modelOverride
      );

    var email =
      model.userEmail || '';

    var role =
      model.userRole || '';

    var emailElement =
      document.getElementById(
        'workspaceUserEmail'
      );

    var roleElement =
      document.getElementById(
        'workspaceUserRole'
      );

    var avatarElement =
      document.getElementById(
        'workspaceUserAvatar'
      );

    if (emailElement) {
      emailElement.textContent =
        email || 'Usuario';
    }

    if (roleElement) {
      roleElement.textContent =
        role || 'Sin rol';
    }

    if (avatarElement) {
      avatarElement.textContent =
        getInitial(email);
    }
  }


  function syncSelectedQuery(
    modelOverride
  ) {
    var model =
      getModel(
        modelOverride
      );

    var queryId =
      getSelectedQueryId(
        model
      );

    var queryName =
      getSelectedQueryName(
        model
      );

    var selectedQuery =
      findQueryById(
        queryId,
        model
      );

    if (
      selectedQuery &&
      selectedQuery.name
    ) {
      queryName =
        String(
          selectedQuery.name
        ).trim();
    }

    var nameElement =
      document.getElementById(
        'activeQueryName'
      );

    var statusElement =
      document.querySelector(
        '.context-status'
      );

    if (nameElement) {
      nameElement.textContent =
        queryName ||
        'Seleccionar consulta';
    }

    if (statusElement) {
      statusElement.style.opacity =
        queryId
          ? '1'
          : '0.35';

      if (
        queryId &&
        selectedQuery &&
        selectedQuery.status === 'inactive'
      ) {
        statusElement.style.background =
          '#9CA3AF';

        statusElement.style.boxShadow =
          '0 0 0 4px rgba(156, 163, 175, 0.12)';
      } else {
        statusElement.style.background =
          '#47D7A0';

        statusElement.style.boxShadow =
          '0 0 0 4px rgba(71, 215, 160, 0.12)';
      }
    }
  }


  function createQueryOption(
    query,
    selectedQueryId
  ) {
    var queryId =
      String(
        query &&
        query.id ||
        ''
      ).trim();

    var queryName =
      String(
        query &&
        query.name ||
        'Consulta sin nombre'
      ).trim();

    var isSelected =
      queryId !== '' &&
      queryId ===
        selectedQueryId;

    var isActive =
      query &&
      query.status === 'active';

    var button =
      document.createElement(
        'button'
      );

    button.type =
      'button';

    button.className =
      'query-selector-option' +
      (
        isSelected
          ? ' selected'
          : ''
      );

    button.setAttribute(
      'role',
      'option'
    );

    button.setAttribute(
      'aria-selected',
      isSelected
        ? 'true'
        : 'false'
    );

    button.setAttribute(
      'data-query-id',
      queryId
    );

    var status =
      document.createElement(
        'span'
      );

    status.className =
      'query-selector-option__status' +
      (
        isActive
          ? ''
          : ' inactive'
      );

    var copy =
      document.createElement(
        'span'
      );

    copy.className =
      'query-selector-option__copy';

    var title =
      document.createElement(
        'strong'
      );

    title.textContent =
      queryName;

    var meta =
      document.createElement(
        'small'
      );

    meta.textContent =
      (
        isActive
          ? 'Activa'
          : 'Inactiva'
      ) +
      (
        query &&
        query.use_web === true
          ? ' · Web'
          : ''
      );

    var check =
      document.createElement(
        'span'
      );

    check.className =
      'query-selector-option__check';

    check.textContent =
      isSelected
        ? '✓'
        : '';

    copy.appendChild(
      title
    );

    copy.appendChild(
      meta
    );

    button.appendChild(
      status
    );

    button.appendChild(
      copy
    );

    button.appendChild(
      check
    );

    return button;
  }


  function renderQuerySelector(
    modelOverride
  ) {
    var model =
      getModel(
        modelOverride
      );

    var queries =
      getQueries(
        model
      );

    var selectedQueryId =
      getSelectedQueryId(
        model
      );

    var listElement =
      document.getElementById(
        'querySelectorList'
      );

    var countElement =
      document.getElementById(
        'querySelectorCount'
      );

    if (countElement) {
      countElement.textContent =
        String(
          queries.length
        );
    }

    if (!listElement) {
      return;
    }

    listElement.innerHTML =
      '';

    if (
      queries.length === 0
    ) {
      var empty =
        document.createElement(
          'div'
        );

      empty.className =
        'query-selector-empty';

      var emptyTitle =
        document.createElement(
          'strong'
        );

      emptyTitle.textContent =
        'Sin consultas disponibles';

      var emptyText =
        document.createElement(
          'span'
        );

      emptyText.textContent =
        'Crea una consulta desde el Constructor para seleccionarla aquí.';

      empty.appendChild(
        emptyTitle
      );

      empty.appendChild(
        emptyText
      );

      listElement.appendChild(
        empty
      );

      return;
    }

    queries.forEach(
      function (query) {
        listElement.appendChild(
          createQueryOption(
            query,
            selectedQueryId
          )
        );
      }
    );
  }


  function positionQuerySelector() {
    var shell =
      document.querySelector(
        '.workspace-shell'
      );

    var button =
      document.getElementById(
        'activeQueryButton'
      );

    var dropdown =
      document.getElementById(
        'querySelectorDropdown'
      );

    if (
      !shell ||
      !button ||
      !dropdown ||
      dropdown.hidden
    ) {
      return;
    }

    var shellRect =
      shell.getBoundingClientRect();

    var buttonRect =
      button.getBoundingClientRect();

    var dropdownRect =
      dropdown.getBoundingClientRect();

    var left =
      buttonRect.right -
      shellRect.left -
      dropdownRect.width;

    var minimumLeft =
      8;

    var maximumLeft =
      shellRect.width -
      dropdownRect.width -
      8;

    left =
      Math.max(
        minimumLeft,
        Math.min(
          left,
          maximumLeft
        )
      );

    var top =
      buttonRect.bottom -
      shellRect.top +
      6;

    dropdown.style.left =
      left + 'px';

    dropdown.style.top =
      top + 'px';
  }


  function setQuerySelectorOpen(
    shouldOpen
  ) {
    var button =
      document.getElementById(
        'activeQueryButton'
      );

    var dropdown =
      document.getElementById(
        'querySelectorDropdown'
      );

    if (
      !button ||
      !dropdown
    ) {
      return;
    }

    querySelectorOpen =
      shouldOpen === true;

    dropdown.hidden =
      !querySelectorOpen;

    button.classList.toggle(
      'is-open',
      querySelectorOpen
    );

    button.setAttribute(
      'aria-expanded',
      querySelectorOpen
        ? 'true'
        : 'false'
    );

    if (querySelectorOpen) {
      renderQuerySelector();
      positionQuerySelector();
    }
  }


  function toggleQuerySelector() {
    setQuerySelectorOpen(
      !querySelectorOpen
    );
  }


  async function selectQuery(
    queryId
  ) {
    var id =
      String(
        queryId || ''
      ).trim();

    if (!id) {
      return;
    }

    var query =
      findQueryById(
        id
      );

    if (!query) {
      return;
    }

    var name =
      String(
        query.name || ''
      ).trim();

    try {
      await appsmith.updateModel({
        selectedQueryId:
          id,

        selectedQueryName:
          name
      });

      syncSelectedQuery();

      renderQuerySelector();

      setQuerySelectorOpen(
        false
      );

      appsmith.triggerEvent(
        'onSelectQuery'
      );

    } catch (error) {
      console.error(
        'No fue posible seleccionar la consulta:',
        error
      );
    }
  }


  async function restoreNavigationModel() {
    if (navigationSyncPending) {
      return;
    }

    navigationSyncPending = true;

    try {
      await appsmith.updateModel({
        activeSection:
          currentSection,

        activeTab:
          currentTab
      });

    } catch (error) {
      console.error(
        'No fue posible restaurar la navegación:',
        error
      );

    } finally {
      navigationSyncPending = false;
    }
  }


  function syncNavigation(
    modelOverride
  ) {
    var model =
      getModel(
        modelOverride
      );

    var modelSection =
      normalizeValue(
        model.activeSection
      );

    var modelTab =
      normalizeValue(
        model.activeTab
      );

    /*
     * Si el modelo coincide con la sección que
     * controla actualmente el Workspace, se admite
     * también un cambio válido de vista interna.
     */
    if (
      modelSection ===
        currentSection &&
      isValidTabForSection(
        modelTab,
        currentSection
      )
    ) {
      currentTab =
        modelTab;

      setActiveSectionVisual(
        currentSection
      );

      return;
    }

    /*
     * Si otro cambio del Default Model intenta
     * devolver la navegación a summary, preservamos
     * la sección y vista que el usuario está usando.
     */
    setActiveSectionVisual(
      currentSection
    );

    restoreNavigationModel();
  }


  function syncShell(
    modelOverride
  ) {
    var model =
      getModel(
        modelOverride
      );

    syncUser(
      model
    );

    syncSelectedQuery(
      model
    );

    renderQuerySelector(
      model
    );

    syncNavigation(
      model
    );

    if (querySelectorOpen) {
      positionQuerySelector();
    }
  }


  async function changeSection(
    sectionId
  ) {
    var section =
      normalizeValue(
        sectionId
      );

    if (
      !isValidSection(
        section
      )
    ) {
      return;
    }

    setQuerySelectorOpen(
      false
    );

    if (
      section ===
      currentSection
    ) {
      setActiveSectionVisual(
        section
      );

      return;
    }

    var nextTab =
      getDefaultTab(
        section
      );

    currentSection =
      section;

    currentTab =
      nextTab;

    setActiveSectionVisual(
      currentSection
    );

    try {
      await appsmith.updateModel({
        activeSection:
          currentSection,

        activeTab:
          currentTab
      });

    } catch (error) {
      console.error(
        'No fue posible cambiar la sección:',
        error
      );
    }
  }


  function bindTabs() {
    var tabs =
      document.querySelectorAll(
        '.workspace-tab'
      );

    tabs.forEach(
      function (tab) {
        tab.setAttribute(
          'role',
          'tab'
        );

        tab.addEventListener(
          'click',
          function () {
            changeSection(
              tab.getAttribute(
                'data-section'
              )
            );
          }
        );
      }
    );
  }


  function bindQuerySelector() {
    var button =
      document.getElementById(
        'activeQueryButton'
      );

    var dropdown =
      document.getElementById(
        'querySelectorDropdown'
      );

    var list =
      document.getElementById(
        'querySelectorList'
      );

    if (button) {
      button.addEventListener(
        'click',
        function (event) {
          event.preventDefault();
          event.stopPropagation();

          toggleQuerySelector();
        }
      );
    }

    if (dropdown) {
      dropdown.addEventListener(
        'click',
        function (event) {
          event.stopPropagation();
        }
      );
    }

    if (list) {
      list.addEventListener(
        'click',
        function (event) {
          var option =
            event.target.closest(
              '[data-query-id]'
            );

          if (!option) {
            return;
          }

          selectQuery(
            option.getAttribute(
              'data-query-id'
            )
          );
        }
      );
    }

    document.addEventListener(
      'click',
      function () {
        if (querySelectorOpen) {
          setQuerySelectorOpen(
            false
          );
        }
      }
    );

    document.addEventListener(
      'keydown',
      function (event) {
        if (
          event.key === 'Escape' &&
          querySelectorOpen
        ) {
          setQuerySelectorOpen(
            false
          );

          if (button) {
            button.focus();
          }
        }
      }
    );

    window.addEventListener(
      'resize',
      function () {
        if (querySelectorOpen) {
          positionQuerySelector();
        }
      }
    );
  }


  bindTabs();
  bindQuerySelector();

  /*
   * Regla aprobada:
   * cada carga del Workspace comienza en Resumen.
   */
  currentSection =
    'summary';

  currentTab =
    'summary';

  syncShell();


  if (
    typeof appsmith.onModelChange ===
    'function'
  ) {
    appsmith.onModelChange(
      function (newModel) {
        syncShell(
          newModel
        );
      }
    );
  }

});
